def fish(cx, cy, s, c):
    return [O(cx, cy, round(36 * s), round(16 * s), c, 14), P([(round(cx + 30 * s), cy), (round(cx + 52 * s), round(cy - 16 * s)), (round(cx + 52 * s), round(cy + 16 * s))], c),
            O(round(cx - 20 * s), round(cy - 4 * s), 3, 3, IN)]


def coin(cx, cy, r, c):
    return [O(cx, cy, r, r, c, 16), O(cx, cy, r - 6, r - 6, SS, 16), O(cx, cy, r - 9, r - 9, c, 16)]


def bubble(x, y, w, h, c, tail):
    return [R(x, y, w, h, c), P([(tail, y + h), (tail + 14, y + h), (tail + 2, y + h + 14)], c)]


